"""Render rows of strings as a GitHub markdown table."""


def _line(cells):
    return "| " + " | ".join(cells) + " |"


def _cell(text):
    return text.strip().replace("|", "\\|")


def to_markdown(rows):
    """Render rows as a markdown table. The first row is the header; no trailing newline."""
    if not rows:
        raise ValueError("no rows")
    header = rows[0]
    if not header:
        raise ValueError("header has no cells")
    for number, row in enumerate(rows[1:], start=2):
        if len(row) != len(header):
            raise ValueError(f"row {number} has {len(row)} cells, header has {len(header)}")
    lines = [_line([_cell(c) for c in header]), _line(["---"] * len(header))]
    lines += [_line([_cell(c) for c in row]) for row in rows[1:]]
    return "\n".join(lines)

