def _run(a):
    try:
        return COMMANDS[a.cmd]["run"](a)
    except ValueError as e:
        print(f"error: {e}", file=sys.stderr)
        return 2


def main(argv=None):
    p = argparse.ArgumentParser(prog="textkit")
    p.add_argument("--json", action="store_true",
                   help="print one JSON object with the command's output lines instead")
    sub = p.add_subparsers(dest="cmd", required=True)
    for name, c in COMMANDS.items():
        sp = sub.add_parser(name, help=c["help"])
        for flag, kw in c["args"]:
            sp.add_argument(flag, **kw)
    a = p.parse_args(argv)
    if not a.json:
        return _run(a)
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        code = _run(a)
    lines = buf.getvalue().split("\n")
    if lines[-1] == "":
        lines.pop()
    print(json.dumps({"command": a.cmd, "exit": code, "output": lines}))
    return code

import contextlib
import io
import unittest

from textkit import mdtable
from textkit.cli import main


def run(stdin_text, *argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err), \
            contextlib.redirect_stdin(io.StringIO(stdin_text)):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class MdtableTest(unittest.TestCase):
    def test_header_separator_and_rows(self):
        self.assertEqual(
            mdtable.to_markdown([["a", "b"], ["1", "2"]]),
            "| a | b |\n| --- | --- |\n| 1 | 2 |",
        )

    def test_header_only(self):
        self.assertEqual(mdtable.to_markdown([["a"]]), "| a |\n| --- |")

    def test_strips_cells(self):
        self.assertEqual(
            mdtable.to_markdown([[" a ", "b\t"], [" 1 ", " 2\n"]]),
            "| a | b |\n| --- | --- |\n| 1 | 2 |",
        )

    def test_escapes_pipes(self):
        self.assertEqual(
            mdtable.to_markdown([["x|y"], ["a | b"]]),
            "| x\\|y |\n| --- |\n| a \\| b |",
        )

    def test_no_rows_raises(self):
        with self.assertRaises(ValueError):
            mdtable.to_markdown([])

    def test_empty_header_raises(self):
        with self.assertRaises(ValueError):
            mdtable.to_markdown([[]])
        with self.assertRaises(ValueError):
            mdtable.to_markdown([[], ["1"]])

    def test_short_row_raises(self):
        with self.assertRaises(ValueError):
            mdtable.to_markdown([["a", "b"], ["1"]])

    def test_long_row_raises(self):
        with self.assertRaises(ValueError):
            mdtable.to_markdown([["a"], ["1", "2"]])

    def test_cli_prints_table(self):
        self.assertEqual(
            run("a,b\n1,2\n", "mdtable"),
            (0, "| a | b |\n| --- | --- |\n| 1 | 2 |\n", ""),
        )

    def test_cli_ragged_csv_exits_2(self):
        code, out, err = run("a,b\n1\n", "mdtable")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "))
